import { pool } from "./db"; // Assuming pool is exported from your db file

export async function deleteCustomer(customerId: string): Promise<void> {
  try {
    await pool.query("BEGIN"); // Start a transaction

    // Delete customer's orders first
    await pool.query("DELETE FROM orders WHERE customer_id = $1", [customerId]);

    // Then delete the customer
    await pool.query("DELETE FROM customers WHERE id = $1", [customerId]);

    await pool.query("COMMIT"); // Commit the transaction
  } catch (error) {
    await pool.query("ROLLBACK"); // Rollback on error
    console.error("Error deleting customer and their orders:", error);
    throw error; // Re-throw the error for the caller to handle
  }
}
